class Solution:
    def deleteDuplicates(self, head: Optional[ListNode]) -> Optional[ListNode]:
        dummy = ListNode(0,head)
        prev=dummy
        curr=head

        while curr:
            dup=curr.val
            if curr.next and curr.next.val==dup:
                while curr and curr.val==dup:
                    curr=curr.next
                prev.next=curr
            else:
                prev=curr
                curr=curr.next
        return dummy.next

