        List<String> wordsList = new ArrayList<String>();
        for (String word : words) {
            String lowerCaseWord = word.toLowerCase();
            boolean flag = true;
            char[] array = lowerCaseWord.toCharArray();
            if (array.length == 0) {
                wordsList.add(word);
