            char c0 = array[0];
            int prevRow = letterRowMap.get(c0);
            for (char c : array) {
                int curRow = letterRowMap.get(c);
                if (curRow != prevRow) {
                    flag = false;
                    break;
                }
                prevRow = curRow;
            }
            if (flag)
                wordsList.add(word);
        }
        int length = wordsList.size();
        String[] rowWords = new String[length];
        for (int i = 0; i < length; i++)
            rowWords[i] = wordsList.get(i);
        return rowWords;
    }
