public class Sum_range_BST {
    public int rangeSumBST(TreeNode root, int L, int R) {
        if (root==null) return 0;
        if (root.val < L) return rangeSumBST(root.right, L, R);
        if (root.val > R) return rangeSumBST(root.left, L, R);
